from pathlib import Pathimport jsonimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltROOT = Path(__file__).resolve().parent.parentRAW = ROOT / 'data' / 'raw'PROCESSED = ROOT / 'data' / 'processed'RESULTS = ROOT / 'results'PROCESSED.mkdir(parents=True, exist_ok=True)RESULTS.mkdir(parents=True, exist_ok=True)HISTORY = RAW / 'multisat_2024_gp_history.json'SAMPLE = RAW / 'multisat_2024_sample.csv'KP = PROCESSED / 'kp_daily_2024-04-01_to_2024-06-30.csv'PANEL_FILE = PROCESSED / 'multisat_2024_daily_decay_kp.csv'SUMMARY_FILE = RESULTS / 'multisat_2024_summary.csv'FIG1 = RESULTS / 'multisat_2024_altitude_vs_storm_effect.png'FIG2 = RESULTS / 'multisat_2024_decay_by_altitude_band.png'BINS = [200, 350, 500, 650, 800]LABELS = ['200-350 km', '350-500 km', '500-650 km', '650-800 km']def load_data():    for p in (HISTORY, SAMPLE, KP):        if not p.exists():            raise FileNotFoundError(f'Missing {p}. Run the matching download script first.')    df = pd.DataFrame(json.loads(HISTORY.read_text()))    df['norad_id'] = pd.to_numeric(df['NORAD_CAT_ID'], errors='coerce')    df['epoch'] = pd.to_datetime(df['EPOCH'], utc=True, errors='coerce')    df['mean_motion'] = pd.to_numeric(df['MEAN_MOTION'], errors='coerce')    df = df.dropna(subset=['norad_id', 'epoch', 'mean_motion'])    df = df[df.mean_motion > 0].copy()    df['norad_id'] = df['norad_id'].astype(int)    n = df['mean_motion'] * (2*np.pi/86400)    df['altitude_km'] = (398600.4418 / n**2)**(1/3) - 6371.0    df['date'] = df['epoch'].dt.floor('D')    daily = df.groupby(['norad_id','date'], as_index=False)['altitude_km'].median()    daily = daily.sort_values(['norad_id','date'])    groups = daily.groupby('norad_id')    daily['elapsed_days'] = groups['date'].diff().dt.total_seconds()/86400    daily['decay_km_day'] = -groups['altitude_km'].diff()/daily['elapsed_days']    # Do not silently connect missing days with a daily Kp label.    daily.loc[daily['elapsed_days'] != 1, 'decay_km_day'] = np.nan    kp = pd.read_csv(KP)    kp['date'] = pd.to_datetime(kp['date'], utc=True)    kp['daily_max_kp'] = pd.to_numeric(kp['daily_max_kp'], errors='coerce')    panel = daily.merge(kp[['date','daily_max_kp']], on='date', how='left', validate='many_to_one')    panel['storm_day'] = panel['daily_max_kp'] >= 5    panel['altitude_band'] = pd.cut(panel['altitude_km'], bins=BINS, labels=LABELS, right=False)    panel.to_csv(PANEL_FILE, index=False)    return paneldef summarize(panel):    window = panel[(panel.date >= '2024-05-01') & (panel.date <= '2024-05-21')].copy()    window = window.dropna(subset=['decay_km_day','daily_max_kp','altitude_band'])    results = []    for norad_id, sat in window.groupby('norad_id'):        storm = sat[sat.storm_day]['decay_km_day']        nonstorm = sat[~sat.storm_day]['decay_km_day']        # Set a small minimum per condition to avoid single-day comparison.        if len(storm) < 3 or len(nonstorm) < 5:            continue        quiet = nonstorm.mean()        storm_rate = storm.mean()        results.append({            'norad_id': norad_id,            'mean_altitude_km': sat.altitude_km.mean(),            'altitude_band': str(sat.altitude_band.mode().iloc[0]),            'n_storm': len(storm), 'n_nonstorm': len(nonstorm),            'mean_storm_decay_km_day': storm_rate,            'mean_nonstorm_decay_km_day': quiet,            'difference_km_day': storm_rate-quiet,            'percent_change': ((storm_rate-quiet)/quiet*100) if quiet > 0 else np.nan,            'pearson_r': sat[['daily_max_kp','decay_km_day']].corr().iloc[0,1]            if sat.daily_max_kp.nunique() > 1 and sat.decay_km_day.nunique() > 1 else np.nan,        })    summary = pd.DataFrame(results)    if summary.empty:        raise RuntimeError('No satellites had enough complete data for both groups.')    summary.sort_values('mean_altitude_km').to_csv(SUMMARY_FILE, index=False)    print('Satellites with adequate data:', len(summary))    print('\nBy altitude band (medians across satellites):')    print(summary.groupby('altitude_band').agg(        satellites=('norad_id','size'),        median_decay_difference=('difference_km_day','median'),        median_pearson_r=('pearson_r','median')    ).to_string())    print('\nThese are observational associations, NOT estimated causal storm losses.')    return summarydef plot(summary):    fig, ax = plt.subplots(figsize=(10,6))    for band, frame in summary.groupby('altitude_band'):        ax.scatter(frame.mean_altitude_km, frame.difference_km_day, alpha=.7, label=band)    ax.axhline(0, color='gray', linestyle='--')    ax.set(xlabel='Mean approximate orbital altitude (km)',           ylabel='Mean storm − nonstorm decay (km/day)',           title='May 2024: Satellite-level Kp-associated decay differences')    ax.legend(title='Altitude band')    ax.grid(alpha=.25)    fig.tight_layout()    fig.savefig(FIG1, dpi=250)    plt.close(fig)    fig, ax = plt.subplots(figsize=(10,6))    groups = [summary[summary.altitude_band == label].difference_km_day.dropna().values              for label in LABELS]    groups = [(g if len(g) else np.array([np.nan])) for g in groups]    ax.boxplot(groups, labels=LABELS, showfliers=True)    ax.axhline(0, color='gray', linestyle='--')    ax.set(xlabel='Altitude band', ylabel='Mean storm − nonstorm decay (km/day)',           title='May 2024: Distribution of decay differences by altitude')    ax.grid(alpha=.25, axis='y')    fig.tight_layout()    fig.savefig(FIG2, dpi=250)    plt.close(fig)    print('Saved:', FIG1, '\nSaved:', FIG2, '\nSaved:', SUMMARY_FILE)if __name__ == '__main__':    panel = load_data()    result = summarize(panel)    plot(result)